// Where a top-down pick is reachable on the table: IK results (grasp within 4 mm, tilt <= 15 deg, whole cup path solved)
// sampled on a grid. Generated by js/stage/tools/reach.mjs' recipe (see CLAUDE.md); rows = x from -0.10 step 0.02,
// columns = z from +0.40 step -0.025. Used for the cheap hover cursor; runTaskAt still confirms with the real IK.
const X0 = -0.10, DX = 0.02, Z0 = 0.40, DZ = -0.025
const ROWS = [
  "000000000000000000000000000000000",
  "000000000000000000000000000000000",
  "000000000000000000000000000000000",
  "000001100000000000000000000000000",
  "000001111100000000000000000000000",
  "000001111111000000000000000000000",
  "000001111111000000000110000000000",
  "000001111111000000000111100000000",
  "000001111111000000000111111100000",
  "000001111111000000000111111100000",
  "000001101111000000000111101100000",
  "000001111111100000001111111100000",
  "000001111111110000011111111100000",
  "000000111111111111111111111000000",
  "000000111111111111111111111000000",
  "000000011111111111111111110000000",
  "000000011111111111111111110000000",
  "000000001111111111111111100000000",
  "000000000111111111111111000000000",
  "000000000011111111111110000000000",
  "000000000001111111111100000000000",
  "000000000000011111110000000000000",
  "000000000000000000000000000000000",
  "000000000000000000000000000000000",
  "000000000000000000000000000000000",
  "000000000000000000000000000000000",
  "000000000000000000000000000000000",
  "000000000000000000000000000000000"
]

export function reachSample(x, z) {
  const r = Math.round((x - X0) / DX), c = Math.round((z - Z0) / DZ)
  if (r < 0 || r >= ROWS.length || c < 0 || c >= ROWS[0].length) return false
  return ROWS[r][c] === '1'
}
